    + 'body.wbx-active .claw-workspace, body.wbx-active .claw-container, body.wbx-active .claw-frame,'
    + 'body.wbx-active .assistant-container, body.wbx-active .agent-home, body.wbx-active .agent-container {'
    + '  background: color-mix(in srgb, var(--wbx-panel, rgba(255,255,255,.5)) 12%, transparent) !important; }'
    + 'body.wbx-active [class*="_gridViewItem_"] { background: transparent !important; }'
    + 'body.wbx-active .wb-home-route { background: transparent !important; }'
    + 'body.wbx-active .wb-home-header__title { color: var(--wbx-text) !important; text-shadow: 0 1px 3px rgba(255,255,255,.85), 0 0 14px rgba(255,255,255,.65); }'
    + 'body.wbx-active .wb-home-header__subtitle { color: var(--wbx-sub) !important; text-shadow: 0 1px 3px rgba(255,255,255,.85); }'
    + 'body.wbx-active .wb-scene-tabs__pill { color: var(--wbx-text); background: var(--wbx-panel); border-color: transparent; }'
    + 'body.wbx-active .wb-scene-tabs__pill--active { background: var(--wbx-accent); color: #fff; }'
    + 'body.wbx-active .composer-mock, body.wbx-active [class*="composer"]:not(.wb-home-composer):not([class*="wb-home-composer"]) { background: var(--wbx-panel) !important; }'
    // 文字浮起：柔和白色光晕，让主题色文字在任意壁纸上可读，不必厚重底衬（呼应壁纸可见诉求）
    + 'body.wbx-active .conversation-shell [class*="text"], body.wbx-active .conversation-shell [class*="Text"], body.wbx-active .conversation-shell [class*="message"], body.wbx-active .conversation-shell [class*="Message"] { text-shadow: 0 1px 2px rgba(255,255,255,.85), 0 0 1px rgba(255,255,255,.55); }'
    // 侧栏通透模式：UI 底衬近乎全透让人物完全显露，改用白色描边光晕保证文字在立绘上仍可读
    + 'body.wbx-active .conversation-sidebar, body.wbx-active .conversation-sidebar * { text-shadow: 0 0 3px rgba(255,255,255,.95), 0 0 7px rgba(255,255,255,.70), 0 1px 2px rgba(255,255,255,.9); }'
